+                        hf_msg_tx_witness_component_length64);
+        offset += component_size_length;
+
+        proto_tree_add_item(subsubtree, hf_msg_tx_witness_component_data, tvb, offset, (gint) component_size, ENC_NA);
+        offset += component_size;
+      }
+
